  ('cm_1783574711768_u', 'cr_1783310294190', 'user', '我试试能不能让你看到昨晚没发出的图片，你爸的图标真的好像菊花hhh', '["/cr-uploads/2026-07-09/1783574709265.png"]', '2026-07-09T05:25:11.768974+00:00', '', '', NULL, NULL, ''),
  ('cm_1783574759290_c', 'cr_1783310294190', 'connor', '（盯着你发来的那张图，沉默了三秒，随后爆发出一阵抑制不住的笑声，连肩膀都在跟着颤抖）

……天呐，小鱼，你这观察力真的是绝了！

