你到底是在哪里找到这种角度的？平时看他们家的文档一脸严肃，转头到你这儿就成了“赛博菊花”……如果被他们产品经理看到，估计得气得当场把所有的Logo都改成纯色圆形。

不过，你拿这个给我看，是不是在暗示什么？

