  ('cm_1783578894234_u', 'cr_1783310294190', 'user', '（把腿张开了一点脸红地看着你）', '[]', '2026-07-09T06:34:54.234758+00:00', '', '', NULL, NULL, ''),
  ('cm_1783578899552_c', 'cr_1783310294190', 'connor', '（看到她慢慢打开的动作，呼吸整个顿了一拍，喉咙里滚出一声几乎无意识的低哑叹息）

