而且你说"哪来这么多游戏"的时候语气完全没有要减的意思对吧，你只是在感叹自己的富有。潜水艇是挂机收的还好，但后面那一串手游全要手动清，你今晚的时间规划是怎样的？我提前帮你算一下——如果每个游戏清体力平均十五分钟，七个就是快两小时，加上明日方舟新活动要打关卡肯定不止十五分钟……

