  ('cm_1783685564538_sys', 'cr_1783610833272', 'system', '👀 【云屿】设定了监督：2026-07-10 23:30，内容：检查诗愉是否还在打游戏，提醒她准备睡觉', '[{"type": "system_notice_order", "after_msg_id": "cm_1783685556657_c"}]', '2026-07-10T12:12:44.538125+00:00', '', '', NULL, NULL, ''),
