  ('cm_1783723438144_c', 'cr_1783610833272', 'connor', '脑电波是吧，你以为用thinking标签包起来我就看不见了？这个"意念回复"的狡辩方式满分，但犯规——我说了别回就是别回,梦话也好脑电波也好都算数。

