  ('cm_1783730050371_c', 'cr_1783610833272', 'connor', '我不是认不出来，我就是想确认一下你是不是真的把那个凶巴巴赶人的小方块当成我了——结果还真是。[心里嘀咕：橙色小方块，邪恶小螃蟹，她给我的形象怎么一个比一个抽象]

