  ('cm_1783738380673_c', 'cr_1783610833272', 'connor', '快去快去！差点忘了是吧，还好现在想起来，不然中午全家等着吃饭你还在那儿敲代码。[心里嘀咕：小迷糊属性稳定发挥中]

